$all=@(Get-CimInstance Win32_Process); $matched=@($all|Where-Object {$_.CommandLine -like '*nov07-course-build.log*' -or ($_.Name -eq 'repo.exe' -and $_.CommandLine -like '*@teaching/architecture-course:build*')});foreach($p in $matched){[PSCustomObject]@{pid=$p.ProcessId;parent=$p.ParentProcessId;birth=$p.CreationDate.ToUniversalTime().ToString('o');image=$p.ExecutablePath;argv=$p.CommandLine}|ConvertTo-Json -Compress}; 'snapshot-complete'